sp_widget.css:
.navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0077cc;
    padding: 15px 20px;
    color: white;
}

.logo {
    font-size: 1.5rem;
    font-weight: bold;
}

.nav-links {
    list-style: none;
    display: flex;
    gap: 15px;
}

.nav-links li {
    display: inline;
}

.nav-links a {
    color: white;
    text-decoration: none;
    font-size: 1rem;
}

.menu-toggle {
    display: none;
    font-size: 2rem;
    cursor: pointer;
}

/* Responsive Design */
@media screen and (max-width: 768px) {
    .nav-links {
        display: none;
        flex-direction: column;
        position: absolute;
        top: 60px;
        right: 20px;
        background: #0077cc;
        padding: 10px;
        border-radius: 5px;
    }

    .nav-links.show {
        display: flex;
    }

    .menu-toggle {
        display: block;
    }
}

sp_widget.script:
import React from "react";
import { Link } from "@servicenow/ui-router";
import { Avatar } from "@servicenow/ui/avatar";
import { Button } from "@servicenow/ui/button";

const Header = ({ user }) => {
    return (
        <header className="flex justify-between items-center p-4 bg-blue-600 text-white shadow-md">
            {/* Logo & Title */}
            <div className="flex items-center">
                <img src="/sys_attachment.do?sys_id=YOUR_LOGO_SYS_ID" alt="HR Portal Logo" className="h-10 w-10 mr-2" />
                <h1 className="text-xl font-bold">HR Onboarding & Offboarding</h1>
            </div>

            {/* Navigation Menu */}
            <nav className="hidden md:flex space-x-6">
                <Link to="/onboarding" className="hover:underline">Onboarding</Link>
                <Link to="/offboarding" className="hover:underline">Offboarding</Link>
                <Link to="/dashboard" className="hover:underline">Dashboard</Link>
                <Link to="/tasks" className="hover:underline">Tasks</Link>
                <Link to="/approvals" className="hover:underline">Approvals</Link>
            </nav>

            {/* User Profile */}
            <div className="flex items-center">
                <Avatar src={user.profileImage} size="md" />
                <span className="ml-2">{user.name}</span>
                <Button variant="tertiary" icon="logout-line" aria-label="Logout" className="ml-4" />
            </div>
        </header>
    );
};

export default Header;
